import itertools, sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
L = list(L)
N = 15
# Precompute all possible triples a+b=c with distinct elements
tuples = []
for a, b, c in itertools.permutations(L, 3):
    if a + b == c:
        # enforce ordering to avoid duplicates (a<=b)
        if a <= b:
            tuples.append((a, b, c))
# Build adjacency for backtracking
used = set()
solution = []

def backtrack():
    if len(solution) == N:
        return True
    # pick smallest unused element to reduce branching
    remaining = [x for x in L if x not in used]
    if not remaining:
        return False
    pivot = min(remaining)
    # try triples that contain pivot as a or b
    for a, b, c in tuples:
        if pivot not in (a, b):
            continue
        if a in used or b in used or c in used:
            continue
        used.update([a, b, c])
        solution.append((a, b, c))
        if backtrack():
            return True
        solution.pop()
        used.difference_update([a, b, c])
    return False

found = backtrack()
if not found:
    print('WITNESS:', json.dumps({"polarity":"negative","basis":"search","search_exhausted":True,"method":"backtrack"}))
    sys.exit(1)
# Prepare result
result = {"triples": solution}
print('WITNESS:', json.dumps({"polarity":"positive","data":result}))

import sys, json

def find_partition(nums):
    nums_set = set(nums)
    # generate all possible triples (a,b,c) with a+b=c and all distinct
    triples = []
    n = len(nums)
    for i in range(n):
        a = nums[i]
        for j in range(i+1, n):
            b = nums[j]
            c = a + b
            if c in nums_set and c != a and c != b:
                # ensure distinct indices
                if c not in (a, b):
                    triples.append((a, b, c))
    # backtracking exact cover
    used = set()
    solution = []
    triples_by_element = {}
    for t in triples:
        for x in t:
            triples_by_element.setdefault(x, []).append(t)
    def backtrack():
        if len(solution) == 15:
            return True
        # pick unused element with fewest candidate triples
        candidates = [x for x in nums if x not in used]
        if not candidates:
            return False
        element = min(candidates, key=lambda e: len([t for t in triples_by_element.get(e, []) if all(v not in used for v in t)]))
        for t in triples_by_element.get(element, []):
            if any(v in used for v in t):
                continue
            solution.append(t)
            for v in t:
                used.add(v)
            if backtrack():
                return True
            for v in t:
                used.remove(v)
            solution.pop()
        return False
    if backtrack():
        return solution
    return None

L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
partition = find_partition(L)
if partition:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"partition": partition}}
    print(f"WITNESS: {json.dumps(witness)}")
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "nodes_explored": null, "method": "backtrack"}
    print(f"WITNESS: {json.dumps(witness)}")
